/*
 * fhir2.base.template's routine for makeAccessible() (registered in config.json "accessibility-routines").
 * Loaded in the page <head> before accessible.js, so the first call happens before the <body> exists.
 *
 * Two mechanisms:
 *
 * - CSS variables: each variable X is pointed at X-accessible or X-non-accessible, which the
 *   template css (project.css, or a child template's css) defines. This is done immediately, on the
 *   document element, so there's no flash of the other presentation.
 *
 * - CSS classes: each element with class C (as generated by the publisher, e.g. 'unchangedStyle')
 *   is switched to class CAccessible in accessible mode, and back to C otherwise. The css (fhir.css)
 *   defines CAccessible. This needs the elements, so on the first call it waits until the document
 *   has loaded.
 */

var FHIR_BASE_ACCESSIBLE_VARIABLES = [
  "--footer-hyperlink-text-color",
  "--link-text-decoration"
];

var FHIR_BASE_ACCESSIBLE_CLASSES = [
  "unchangedStyle",
  "removedStyle",
  "xhtPieceDeEmphasized"
];

var fhirBaseAccessibleState = false;
var fhirBaseAccessibleWaiting = false;

function fhirBaseMakeAccessible(accessible) {
  var root = document.documentElement.style;
  var suffix = accessible ? "-accessible" : "-non-accessible";
  for (var i = 0; i < FHIR_BASE_ACCESSIBLE_VARIABLES.length; i++) {
    var v = FHIR_BASE_ACCESSIBLE_VARIABLES[i];
    root.setProperty(v, "var(" + v + suffix + ")");
  }

  fhirBaseAccessibleState = accessible;
  if (document.readyState === "loading") {
    if (!fhirBaseAccessibleWaiting) {
      fhirBaseAccessibleWaiting = true;
      document.addEventListener("DOMContentLoaded", function () {
        fhirBaseSwapAccessibleClasses(fhirBaseAccessibleState);
      });
    }
  } else {
    fhirBaseSwapAccessibleClasses(accessible);
  }
}

function fhirBaseSwapAccessibleClasses(accessible) {
  for (var i = 0; i < FHIR_BASE_ACCESSIBLE_CLASSES.length; i++) {
    var c = FHIR_BASE_ACCESSIBLE_CLASSES[i];
    var a = c + "Accessible";
    var elements = document.querySelectorAll(accessible ? "." + c : "." + a);
    for (var j = 0; j < elements.length; j++) {
      elements[j].classList.replace(accessible ? c : a, accessible ? a : c);
    }
  }
}
